(()=>{'use strict';const form=document.getElementById('business-login'),status=document.getElementById('login-status'),parents=['https://mowmatter.com','https://www.mowmatter.com'];let parentOrigin;try{const origin=new URL(document.referrer).origin;if(parents.includes(origin))parentOrigin=origin}catch{}const embedded=window.parent!==window&&!!parentOrigin;function notify(data){if(embedded)window.parent.postMessage(data,parentOrigin)}function enterOffice(){if(embedded)notify({type:'mm-business-signed-in'});else location.assign('/index.html')}function resize(){notify({type:'mm-business-login-height',height:Math.ceil(document.querySelector("main").getBoundingClientRect().height)})}async function run(task){const buttons=[...document.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);status.textContent='Working…';try{await task()}catch(error){status.textContent=error.message||'Unable to sign in. Please try again.'}finally{buttons.forEach(b=>b.disabled=false);resize()}}form.addEventListener('submit',event=>{event.preventDefault();const values=new FormData(form),signup=event.submitter?.value==='signup';void run(async()=>{if(signup){await MM.signUp(values.get('email'),values.get('password'),form.elements.launch_updates.checked);status.textContent='Check your email to confirm your account, then return to sign in.'}else{await MM.signIn(values.get('email'),values.get('password'));form.elements.password.value='';await MM.saveLaunchUpdates(form.elements.launch_updates.checked);status.textContent='Signed in. Opening your business workspace…';enterOffice()}})});for(const [id,method]of [['forgot','resetPassword'],['resend','resend']])document.getElementById(id).addEventListener('click',()=>{const email=form.elements.email;if(!email.checkValidity()||!email.value){email.reportValidity();email.focus();status.textContent='Enter your account email above first.';resize();return}void run(async()=>{await MM[method](email.value);status.textContent='If eligible, an email has been requested. Check your inbox.'})});void MM.ready.then(async()=>{if(typeof MM.launchUpdatesChoice==='boolean')form.elements.launch_updates.checked=MM.launchUpdatesChoice;if(MM.session&&!MM.recovery){if(typeof MM.launchUpdatesChoice==='boolean'){const finish=async()=>{await MM.saveLaunchUpdates(form.elements.launch_updates.checked);enterOffice()};await run(finish);if(typeof MM.launchUpdatesChoice==='boolean'){const retry=document.createElement('button');retry.type='button';retry.className='button primary';retry.textContent='Save update preference and continue';retry.onclick=()=>run(finish);form.after(retry);}}else enterOffice();return}MM.mountGoogleLogin(form);if(embedded)for(const provider of ['google','facebook']){const button=document.querySelector('[data-'+provider+'-login]');if(button)button.onclick=()=>notify({type:'mm-business-login-provider',provider,launchUpdates:form.elements.launch_updates.checked})}resize()});if(typeof ResizeObserver!=='undefined')new ResizeObserver(resize).observe(document.querySelector("main"));})();
